export function publicationMode({coreFileMode, trackedMode, fsMode}) {
  if (coreFileMode) {
    // git add uses only the owner executable bit to decide 100755 vs 100644
    return (fsMode & 0o100) ? "100755" : "100644";
  }
  // core.filemode=false: preserve the tracked mode; new files default to regular 100644
  return trackedMode ?? "100644";
}

